V.mvplan=function(){const o=S.songs[ui.mvs],p=S.pj;if(!o||!p||!(p.mainId==o.id||p.coup.includes(o.id)))return`<div class="c">${emptyBox('Open a song of the current single to plan its Music Video.','🎬')}<button class="b" onclick="goView('music')">← Single Production</button></div>`;
 const v=mvOf(o),lk=lockedSong(o.id),ed=!lk&&v.st=='plan',dis=ed?'':'disabled',c=mvCost(o),due=c.t-(v.paid|0),er=mvErr(o),lt=ui.mvlt||(mvLoc(v.loc).ovs?'ovs':'dom');
 const card=(on,act,art,t,s,x)=>`<button class="mvcard ${on?'on':''}" ${dis} onclick="${act}">${art}<b>${t}</b>${s?`<small>${s}</small>`:''}${x?`<span class="mvc">${x}</span>`:''}</button>`;
 const styles=Object.entries(MV_STY).map(([k,s])=>card(v.style==k,`mvSet('${o.id}','style','${k}')`,mvStyleArt(k),s.n,s.d,`crew ${s.crew} · ${s.days} day(s)${s.vfx?` · VFX from ${yen(s.vfx)}`:''}`)).join('');
 const locs=MV_LOC.filter(L=>lt=='ovs'?L.ovs:!L.ovs).map(L=>{const cc=mvCost(o,{...v,loc:L.id});return card(v.loc==L.id,`mvSet('${o.id}','loc','${L.id}')`,mvLocArt(L),esc(L.n),`${esc(L.city)} · ${esc(L.country)}`,`rent ${yen(L.rent)}/day${L.trav?` · travel ${yen(L.trav)}/person`:''}${L.hotel?` · hotel ${yen(L.hotel)}/night`:''} · est. total ${yen(cc.t)}`)}).join('');
 const stories=MV_STORY.filter(s=>!s.only||v.style=='story').map(s=>`<button class="mvst ${v.story==s.id?'on':''} ${s.only?'ex':''}" ${dis} onclick="mvSet('${o.id}','story','${s.id}')"><b>${s.n}</b><small>${s.id=='none'?'Optional — no story':`${s.sc} scenes · complexity ${'●'.repeat(s.cx)}${'○'.repeat(3-s.cx)}`}</small></button>`).join('');
 const st=v.st,state=`<span class="mvsb ${st}">${MV_ST[st]}</span>`;
 return`<div class="c mvhero"><div>${mvThumb(o,220)}</div><div><span class="thkick">MUSIC VIDEO PLANNING · MV企画</span><h2>“${esc(o.title)}”</h2><div class="st">${o.id==p.mainId?'Title Track':'Coupling Song'} · ${esc(p.title||'Untitled single')} · ${esc(o.genre)} · ${esc(o.concept)}</div><div class="row">${state}<button class="b s" onclick="goView('music')">← Back to Single Production</button>${lk?'':`<button class="b s" onclick="mvToggle('${o.id}',false)">No Music Video</button>`}</div></div></div>
 <div class="c"><h3>1 · MV Style <small class="st">choose one</small></h3><div class="mvgrid">${styles}</div></div>
 <div class="c"><h3>2 · Filming location</h3><div class="row"><button class="b s ${lt=='dom'?'on':''}" onclick="ui.mvlt='dom';render()">🇯🇵 Domestic</button><button class="b s ${lt=='ovs'?'on':''}" onclick="ui.mvlt='ovs';render()">✈ Overseas</button><span class="st">Overseas filming adds flights, hotels, local coordination and extra travel days for the whole team.</span></div><div class="mvgrid loc">${locs}</div></div>
 <div class="c"><h3>3 · Storyline <small class="st">optional${v.style=='story'?' · Story MV unlocks extra storylines':''}</small></h3><div class="mvstg">${stories}</div></div>
 <div class="c"><h3>4 · Senbatsu &amp; costume</h3>${mvSenHtml(o)}</div>
 <div class="c mvbud"><h3>MV Production Estimate</h3><div class="st">${c.shoot} filming day(s) (${c.days}) · crew ${c.crew} · ${c.people} people on set${c.ovs?` · ${c.trav} travelling from Japan, local crew hired on site`:''}</div><table>${c.rows.filter(([,a])=>a>0).map(([n,a])=>`<tr><td>${n}</td><td>${yen(a)}</td></tr>`).join('')}<tr class="tot"><td>Total</td><td>${yen(c.t)}</td></tr>${v.paid?`<tr><td>Already paid</td><td>${yen(v.paid)}</td></tr><tr><td>${due>=0?'To pay now':'Refund'}</td><td>${yen(Math.abs(due))}</td></tr>`:''}</table>
 ${er.map(x=>`<p class="thwarn">⚠ ${esc(x)}</p>`).join('')}${ed&&due>S.money?`<p class="thwarn">⚠ Not enough funds: ${yen(due)} needed, you have ${yen(S.money)}.</p>`:''}
 <div class="row">${lk?`<span class="st">Production has started — this plan is fixed.</span>`:st=='plan'?`<button class="b p" ${er.length||due>S.money?'disabled':''} onclick="mvConfirm('${o.id}')">🎬 Confirm MV production · ${yen(Math.max(0,due))}</button>`:`<span class="tag rrSR">✓ Budget confirmed · ${yen(v.paid)}</span><button class="b s" onclick="mvRevise('${o.id}')">Revise plan</button>`}</div>
 <p class="st">The MV is filmed in Week 3 of the 28-day production, checked in Week 4 and published on the song's Release Day. Budget does not guarantee views — reception decides.</p></div>`};
