const mvAll=()=>Object.values(S.songs||{}).filter(o=>o.mv&&o.mv.st=='published').sort((a,b)=>b.mv.pub-a.mv.pub);
function mvChart(v){const D=v.dh||[],W=Math.max(300,D.length*6),H=110,mx=Math.max(1,...D.map(d=>d.v/d.n));return`<svg class="gechart" viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" role="img" aria-label="Daily views">${D.map((d,i)=>`<rect x="${i*(W/Math.max(1,D.length))}" y="${H-(d.v/d.n)/mx*(H-6)}" width="${Math.max(1.5,W/Math.max(1,D.length)-1)}" height="${(d.v/d.n)/mx*(H-6)}" fill="${(v.ev||[]).some(e=>d.d>=e.d&&d.d<e.d+e.len)?'#e9b949':'#f08bb4'}"><title>${jd(d.d)}${d.n>1?' (+'+(d.n-1)+' days)':''}: ${d.v.toLocaleString()} views</title></rect>`).join('')}</svg><div class="st"><span style="color:#f08bb4">■</span> daily views · <span style="color:#e9b949">■</span> viral / renewed interest · after 60 days one bar per week (daily average)</div>`}
